window.NANO_UI_WIDGET_META = {"button":{"expr":"rowWith (gap 8) $ button \"Save\" >> styled subtle (button \"Subtle\")","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme to `defaultLightTheme` before scoped modifiers run.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Primary","bit":1,"detail":"Colors `Save` (`styleBg`, `styleBorder`, `styleFg`). `Subtle` keeps only its text color because its own `styled subtle` runs after the outer `buttonStyle` and clears the background and border.","impact":"primary","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: the button never reads `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: the button never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"No-op","bit":4,"detail":"No effect. `button` ignores `themeAccent`; use `styled primary` or `toggleButton` to bind it.","impact":"noop","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Sets `styleCornerRadius` to 999, so the button becomes a pill (`rx` = half the height).","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the fill, border and label, and blocks clicks and focus.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"checkbox":{"expr":"checkbox \"Unchecked\" vOff >> checkbox \"Checked\" vOn","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme: light unchecked well, dark label.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Colors the label and unchecked outline. `clearStyle` removes the background, so no button box is drawn.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Partial","bit":2,"detail":"Colors only the 14x14 unchecked well.","impact":"partial","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `checkbox` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the checked box fill and border; the checkmark uses `themeOnAccent`.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Edge case","bit":5,"detail":"Ignored. `paintChoiceIndicator` hardcodes the radius to `min 3 (boxS * 0.2)`.","impact":"surprise","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the boxes, checkmark and label.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"custom-controls":{"expr":"toggleSwitch vSw >> progressBar 0.68 >> sparkline [2, 7, 4, 9, 5, 11, 8, 12]","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme for all three canvas widgets.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Colors the track border and unfilled track of `toggleSwitch` and `progressBar`; `sparkline` ignores it.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: these widgets never read `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"Partial","bit":3,"detail":"Colors only the `sparkline` well; `toggleSwitch` and `progressBar` ignore it.","impact":"partial","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the switch pill, progress fill, and sparkline line and dot.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Edge case","bit":5,"detail":"Ignored. The switch and progress bar use `r = h/2`; the sparkline uses `r = 3`.","impact":"surprise","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims `cdcTheme` in `CustomDrawContext` for all three.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"overlays":{"expr":"window vWin \"Inspector\" (label \"Floating window\")","isOverlay":true,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect until hover. `menuItem` falls back to `styleHoverBg` from `themeButton` only when the popup hover fill equals its fill.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: overlays never read `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"Primary","bit":3,"detail":"Colors the floating window chrome via `windowStyle` and popup menus via `popupStyle`.","impact":"primary","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"No-op","bit":4,"detail":"No effect on standard window chrome.","impact":"noop","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Rounds the floating window corners.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the window chrome, title bar and body.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"panel-card-callout":{"expr":"panel (label \"panel surface\") >> callout amber (label \"Warning callout\")","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect: containers read `themePanel`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: containers never read `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"Primary","bit":3,"detail":"Colors the panel fill, border and child labels. `callout` applies its own tinted `panelStyle` on top.","impact":"primary","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"No-op","bit":4,"detail":"No effect when `callout` uses an explicit color; `calloutTone Accent` binds `themeAccent`.","impact":"noop","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Rounds the panel and callout corners.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the surfaces, borders and labels.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"radio":{"expr":"radio [\"Option A\", \"Option B\"] vSelected","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Colors the labels and the unselected ring stroke. `clearStyle` removes the background.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Partial","bit":2,"detail":"Colors only the unselected ring fill.","impact":"partial","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `radio` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the selected ring and dot.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Edge case","bit":5,"detail":"No effect: radio indicators are always circles (`r = boxS / 2`).","impact":"surprise","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the rings, dot and labels.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"scroll-bounded":{"expr":"scrollWith (fillW . fixedH 64 . padAll 6) $ label \"Row 1\" >> ...","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect: scroll wells never read `themeButton`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Primary","bit":2,"detail":"Unexpected: bounded scroll wells use `themeInput`, not `themePanel`, and blend the scrollbar with it.","impact":"primary","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"Unexpected no-op: the well ignores `panelStyle`; only the child label text reads `themePanel`'s `styleFg`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"No-op","bit":4,"detail":"No effect: the scrollbar blends `themeInput` and `themeSeparator`.","impact":"noop","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Edge case","bit":5,"detail":"Ignored. `paintScrollSurface` forces `styleCornerRadius = 0`, so the well is always square.","impact":"surprise","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the well, scrollbar and labels.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"search-numeric":{"expr":"searchInput \"Search\" vQuery >> numericInput vNum","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect. The stepper buttons in `numericInput` are painted from `themeInput`, not `themeButton`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Primary","bit":2,"detail":"Colors both fields. `searchInput` tints its icons 45% toward the well fill; `numericInput` tints its divider and arrows 40% toward the well fill.","impact":"primary","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: neither input reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Partial","bit":4,"detail":"Used for the focused border and caret.","impact":"partial","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Turns both wells into pills.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the wells, icons, arrows and text.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"select-vs-combo":{"expr":"selectWith fillW [\"Select (btn)\", ...] vIdx >> comboBox \"Pick...\" [...] vCombo","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme on both controls.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Styles `select` only. `comboBox` is a `NodeTextInput` and ignores `buttonStyle`.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Partial","bit":2,"detail":"Styles `comboBox` only. `select` is a `NodeSelect` and ignores `inputStyle`.","impact":"partial","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect on closed controls; open menus read `themePopup`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Partial","bit":4,"detail":"Highlights the selected row in an open menu and the focused `comboBox` border.","impact":"partial","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Rounds `select` via `themeButton` and `comboBox` via `themeInput`.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims both controls and blocks opening their menus.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"slider":{"expr":"sliderWith fillW 0 100 vVal","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect: `slider` reads `themeInput` and `themeAccent`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Partial","bit":2,"detail":"Colors the track outline and thumb border, and blends the unfilled track 35% from `styleBg` toward the border.","impact":"partial","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `slider` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the filled track; the thumb interior uses `themeOnAccent`.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Edge case","bit":5,"detail":"Ignored. `paintSliderNode` hardcodes track radius 3 and border width 1.","impact":"surprise","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the track, fill and thumb.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"table-tree":{"expr":"simpleTable [\"Mod\", \"Surface\"] [...] >> tree \"demo-tree\" [...] vTree","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Blends 55% into the table header fill, and colors the sorted header text, tree labels and odd tree row tint.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: neither `simpleTable` nor `tree` reads `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"Primary","bit":3,"detail":"Colors the table cells, grid borders, header fill and tree row fill.","impact":"primary","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Tints the selected tree row 25% toward `themeAccent` and draws the 2px left bar.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"No-op","bit":5,"detail":"No effect: cells and rows are drawn as sharp edge-to-edge rects.","impact":"noop","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the headers, cells, grid lines and rows.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"tabs-styles":{"expr":"tabBarConfigured (defaultTabsConfig {tabsStyle = ...}) vTab [tab 0 \"Code\" (), tab 1 \"AST\" ()]","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Edge case","bit":1,"detail":"Ignored by `TabUnderline` and `TabPill`. `tabHeaderVisualStyle` reads `themePanel`; only `TabSegmented` reads `styleBorder` from `themeButton`.","impact":"surprise","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: `tabBar` never reads `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"Primary","bit":3,"detail":"Colors inactive and active tab text, the underline rule and the `TabSegmented` well.","impact":"primary","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the underline bar in `TabUnderline` and the active pill fill in `TabPill`.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Partial","bit":5,"detail":"Rounds the `TabSegmented` well and active segment. `TabUnderline` is unaffected; `TabPill` already uses half the height.","impact":"partial","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the tab styles and blocks switching.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"text-input":{"expr":"textInputConfigured (defaultTextInputConfig {ticPlaceholder = \"Filter...\"}) vEmpty >> textInput vText","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect: `textInput` reads `themeInput`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Primary","bit":2,"detail":"Colors the well fill, border, value text and placeholder.","impact":"primary","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `textInput` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Partial","bit":4,"detail":"Used for the focused border and caret.","impact":"partial","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Turns the well into a pill.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the well, border and text, and blocks focus and typing.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"textarea":{"expr":"textAreaWith (fillW . fixedH 64) vDoc","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"No-op","bit":1,"detail":"No effect: `textArea` reads `themeInput`.","impact":"noop","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"Primary","bit":2,"detail":"Colors the well, border and document text.","impact":"primary","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `textArea` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Partial","bit":4,"detail":"Used for the active border and caret.","impact":"partial","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Rounds the editor corners.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims the well and text, and blocks editing.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]},"toggle-button":{"expr":"toggleButton Accent \"Off\" vOff >> toggleButton Accent \"On\" vOn","isOverlay":false,"notes":[{"badge":"Primary","bit":0,"detail":"Switches the base theme. `readableOn` recomputes the on-state text color against the tone color.","impact":"primary","key":"light","label":"defaultLightTheme","short":"Light Theme"},{"badge":"Partial","bit":1,"detail":"Affects the off state only. On, `widgetVisualStyle` replaces the fill, hover fill and border with `toneColor`, and the text with `readableOn`.","impact":"partial","key":"btn","label":"buttonStyle","short":"buttonStyle"},{"badge":"No-op","bit":2,"detail":"No effect: `toggleButton` never reads `themeInput`.","impact":"noop","key":"inp","label":"inputStyle","short":"inputStyle"},{"badge":"No-op","bit":3,"detail":"No effect: `toggleButton` never reads `themePanel`.","impact":"noop","key":"pnl","label":"panelStyle","short":"panelStyle"},{"badge":"Primary","bit":4,"detail":"Colors the on state when the tone is `Accent`; `readableOn` picks black or white text.","impact":"primary","key":"acc","label":"accentColor","short":"accentColor"},{"badge":"Primary","bit":5,"detail":"Applies radius 999 to both states. The on state keeps `styleCornerRadius` from `themeButton`.","impact":"primary","key":"rnd","label":"rounded 999","short":"rounded 999"},{"badge":"Primary","bit":6,"detail":"Dims both states and blocks toggling.","impact":"primary","key":"dis","label":"disabledWhen True","short":"disabledWhen"}]}};
window.NANO_UI_TRAPS = [{"category":"typography surface-button","codeBad":"buttonWith (fontBold . fontUnderline . fontDanger) \"Delete\"\nselectWith (fontBold . fontDanger) [\"Item\"] sel","codeGood":"styled (tinted Danger) $\n  buttonContent (labelWith (fontBold . fontUnderline . fontDanger) \"Delete\")\nselectWith (fontColor coral) [\"Item\"] sel","fix":"Use `fontSize` and `fontColor` on `buttonWith`/`selectWith`/`checkboxWith`. For bold, italic, underline, monospace or `fontTone` inside a button, wrap a `labelWith` in `buttonContent`.","id":"01","labelA":"fontBold, fontUnderline, fontDanger dropped","labelB":"buttonContent for font flags, fontColor for tint","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"91\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"36\" width=\"244\" height=\"26\" rx=\"2\" fill=\"#34343a\"/><rect x=\"8.5\" y=\"36.5\" width=\"243\" height=\"25\" rx=\"1.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><path d=\"M239.8,48.1 L248.2,48.1 L244,51.6 Z\" fill-rule=\"evenodd\" fill=\"#f8f7f5\"/><rect x=\"8\" y=\"8\" width=\"159\" height=\"22\" rx=\"2\" fill=\"#34343a\"/><rect x=\"8.5\" y=\"8.5\" width=\"158\" height=\"21\" rx=\"1.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"12\" y=\"19.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f8f7f5\" textLength=\"151\" lengthAdjust=\"spacing\">buttonWith fontDanger</text><text x=\"13\" y=\"49.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f8f7f5\" textLength=\"148\" lengthAdjust=\"spacing\">selectWith fontDanger</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"91\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"37\" width=\"244\" height=\"26\" rx=\"2\" fill=\"#34343a\"/><rect x=\"8.5\" y=\"37.5\" width=\"243\" height=\"25\" rx=\"1.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><path d=\"M239.8,49.1 L248.2,49.1 L244,52.6 Z\" fill-rule=\"evenodd\" fill=\"#f8f7f5\"/><rect x=\"8\" y=\"8\" width=\"157\" height=\"23\" rx=\"2\" fill=\"#fca5a5\"/><rect x=\"8.5\" y=\"8.5\" width=\"156\" height=\"22\" rx=\"1.5\" stroke=\"#fca5a5\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"12\" y=\"19.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" font-weight=\"bold\" text-decoration=\"underline\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"149\" lengthAdjust=\"spacing\">buttonContent + tinted</text><text x=\"13\" y=\"50.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f87171\" textLength=\"135\" lengthAdjust=\"spacing\">selectWith fontColor</text></svg>","title":"buttonWith drops font flags","where":"NanoUI.Internal.Layout.Arena (packsNodeFont), NanoUI.Internal.Frame.Spans (nodeFontStyle)","why":"Every node shares one `styleIdx` column. Only `NodeText` and `NodeTextInput` pack font data (`FontVariant`, `FontTone`, bold, italic, underline, strike) into it. `NodeButton` and `NodeSelect` overwrite `styleIdx` with widget metadata (`buttonKindToggle`, `buttonFlagChoice`, `TabStyle`, sort arrows). `fontSize` and `fontColor` use separate arena columns, so they still work on buttons and selects."},{"category":"typography surface-panel","codeBad":"heading \"Section\" -- 18px, styleFg(themePanel)\nlabelWith fontHeading \"Section\" -- 14px, themeAccent","codeGood":"labelWith (fontMedium . fontHeading) \"Section\" -- 18px, themeAccent","fix":"Use `fontMedium . fontHeading` for an 18px accent title, or `heading` for 18px in the panel foreground color.","id":"02","labelA":"heading: 18px, panel foreground","labelB":"fontHeading: 14px, accent","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"84\" viewBox=\"0 0 260 84\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"83\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"8\" y=\"16.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" font-weight=\"500\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"226\" lengthAdjust=\"spacing\">heading &quot;Section&quot; (18px, panel fg)</text><text x=\"8\" y=\"39.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"244\" lengthAdjust=\"spacing\">Uses FontRegular + fontMedium (18px)</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"84\" viewBox=\"0 0 260 84\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"83\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"8\" y=\"16.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#589cf6\" textLength=\"244\" lengthAdjust=\"spacing\">labelWith fontHeading (14px, accent)</text><text x=\"8\" y=\"39.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" font-weight=\"500\" xml:space=\"preserve\" fill=\"#589cf6\" textLength=\"244\" lengthAdjust=\"spacing\">fontMedium . fontHeading (18px, accent)</text></svg>","title":"heading and fontHeading differ","where":"NanoUI.Internal.Widgets.Display (heading), NanoUI.Internal.Style (textToneColor)","why":"`heading` is `labelWith (tight . fontMedium)`: it sets 18px with `FontRegular`, so its color is `styleFg (themePanel theme)`. The `fontHeading` modifier sets `layoutFontVariant = FontHeading` and leaves `fontSize` at 14px; `textToneColor` paints `FontHeading` with `themeAccent`."},{"category":"surface-button surface-input surface-popup","codeBad":"-- buttonStyle background is stripped by clearStyle\nstyled (buttonStyle (background red)) (checkbox \"Opt\" v)","codeGood":"styled (inputStyle (background wellBg)\n      . buttonStyle (borderColor ringCol . foreground txtCol)\n      . accentColor checkCol) (checkbox \"Opt\" v)","fix":"Set `inputStyle` for the unchecked well, `buttonStyle` for the ring and label (plus `popupStyle` inside modals), and `accentColor` for the checked state.","id":"03","labelA":"inputStyle well, buttonStyle ring and text, accentColor check","labelB":"inside a modal, ring and label use popupStyle","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"120\" viewBox=\"0 0 260 120\"><defs><clipPath id=\"i3-bad-tclip_1\"><rect x=\"35.5\" y=\"10\" width=\"223.4\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"120\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"120\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"119\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"10\" y=\"61.2\" width=\"15.5\" height=\"15.5\" rx=\"7.8\" fill=\"#047857\"/><rect x=\"9\" y=\"60.2\" width=\"17.5\" height=\"17.5\" rx=\"8.8\" stroke=\"#589cf6\" stroke-width=\"2\" fill=\"none\"/><rect x=\"10.7\" y=\"62\" width=\"14.1\" height=\"14.1\" rx=\"7\" fill=\"#589cf6\"/><rect x=\"8\" y=\"34\" width=\"19.5\" height=\"19.5\" rx=\"5.6\" fill=\"#589cf6\"/><rect x=\"8.8\" y=\"34.8\" width=\"18\" height=\"18\" rx=\"4.8\" stroke=\"#589cf6\" stroke-width=\"1.5\" fill=\"none\"/><line x1=\"12.3\" y1=\"44.2\" x2=\"16.2\" y2=\"48.1\" stroke=\"#ffffff\" stroke-width=\"2.2\"/><line x1=\"16.2\" y1=\"48.1\" x2=\"23.2\" y2=\"39.5\" stroke=\"#ffffff\" stroke-width=\"2.2\"/><rect x=\"11.2\" y=\"43.1\" width=\"2.2\" height=\"2.2\" rx=\"1.1\" fill=\"#ffffff\"/><rect x=\"15.1\" y=\"47\" width=\"2.2\" height=\"2.2\" rx=\"1.1\" fill=\"#ffffff\"/><rect x=\"22.2\" y=\"38.4\" width=\"2.2\" height=\"2.2\" rx=\"1.1\" fill=\"#ffffff\"/><rect x=\"9.5\" y=\"9.7\" width=\"16.5\" height=\"16.5\" rx=\"4.1\" fill=\"#047857\"/><rect x=\"8.8\" y=\"9\" width=\"18\" height=\"18\" rx=\"4.8\" stroke=\"#38bdf8\" stroke-width=\"1.5\" fill=\"none\"/></g><g clip-path=\"url(#i3-bad-tclip_1)\"><text x=\"35.5\" y=\"18.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#38bdf8\" textLength=\"230\" lengthAdjust=\"spacing\">Unchecked (input bg + btn border)</text></g><text x=\"35.5\" y=\"43.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#38bdf8\" textLength=\"139\" lengthAdjust=\"spacing\">Checked (accent bg)</text><text x=\"35.5\" y=\"69.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#38bdf8\" textLength=\"221\" lengthAdjust=\"spacing\">Radio ring (input bg + btn border)</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"120\" viewBox=\"0 0 260 120\"><defs><clipPath id=\"i3-good-tclip_1\"><rect x=\"24\" y=\"31.7\" width=\"212\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"120\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"120\" fill=\"#08080a\" fill-opacity=\"0.69\"/><rect x=\"17\" y=\"22.7\" width=\"232\" height=\"80.6\" rx=\"2\" fill=\"#000000\" fill-opacity=\"0.282\"/><rect x=\"14\" y=\"19.7\" width=\"232\" height=\"80.6\" rx=\"2\" fill=\"#222226\"/><rect x=\"14.5\" y=\"20.2\" width=\"231\" height=\"79.6\" rx=\"1.5\" stroke=\"#fbbf24\" stroke-width=\"1\" fill=\"none\"/><rect x=\"24\" y=\"68.7\" width=\"212\" height=\"19.5\" fill=\"#222226\"/><rect x=\"25.5\" y=\"70.2\" width=\"16.5\" height=\"16.5\" rx=\"4.1\" fill=\"#121215\"/><rect x=\"24.8\" y=\"69.5\" width=\"18\" height=\"18\" rx=\"4.8\" stroke=\"#fbbf24\" stroke-width=\"1.5\" fill=\"none\"/><rect x=\"14\" y=\"59.7\" width=\"232\" height=\"1\" fill=\"#3e4048\"/></g><g clip-path=\"url(#i3-good-tclip_1)\"><text x=\"24\" y=\"40.2\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"223\" lengthAdjust=\"spacing\">Inside modal (reads themePopup)</text></g><text x=\"51.5\" y=\"78.2\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#fbbf24\" textLength=\"157\" lengthAdjust=\"spacing\">Switched to popupStyle</text></svg>","title":"checkbox and radio span three surfaces","where":"NanoUI.Internal.Frame.Chrome (widgetVisualStyle), NanoUI.Internal.Frame.Paint.Widgets (paintCheckboxNode)","why":"Choice widgets run `clearStyle (modalAware (themeButton theme))`, which zeroes `styleBg`, `styleHoverBg`, `styleActiveBg` and `styleBorderWidth`. Paint then reads the unchecked well fill from `styleBg (themeInput theme)`, the ring and label from `themeButton`'s `styleBorder` and `styleFg`, and the checked fill and mark from `themeAccent` and `themeOnAccent`. Inside a `modal`, `modalAware` swaps the ring and label to `themePopup`."},{"category":"surface-button surface-input","codeBad":"-- select stays on themeButton under inputStyle\nstyled (inputStyle myFieldStyle) $ do\n  comboBox opts vCombo\n  select opts vIdx","codeGood":"styled (inputStyle myFieldStyle . buttonStyle myFieldStyle) $ do\n  comboBox opts vCombo\n  select opts vIdx","fix":"Apply the same style to `inputStyle` and `buttonStyle`, or wrap `select` in `styled (buttonStyle ...)`.","id":"04","labelA":"inputStyle only: comboBox changes, select stays","labelB":"inputStyle and buttonStyle match","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"91\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"41\" width=\"244\" height=\"26\" rx=\"2\" fill=\"#34343a\"/><rect x=\"8.5\" y=\"41.5\" width=\"243\" height=\"25\" rx=\"1.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><path d=\"M239.8,53.1 L248.2,53.1 L244,56.6 Z\" fill-rule=\"evenodd\" fill=\"#f8f7f5\"/><rect x=\"8\" y=\"8\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#047857\"/><rect x=\"9\" y=\"9\" width=\"242\" height=\"25\" rx=\"1\" stroke=\"#34d399\" stroke-width=\"2\" fill=\"none\"/><path d=\"M239.8,20.6 L248.2,20.6 L244,24.1 Z\" fill-rule=\"evenodd\" fill=\"#75c0a5\"/></g><text x=\"13\" y=\"21.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#d1fae5\" textLength=\"124\" lengthAdjust=\"spacing\">comboBox (styled)</text><text x=\"13\" y=\"54.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f8f7f5\" textLength=\"173\" lengthAdjust=\"spacing\">select (ignores inputStyle)</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"91\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"41\" width=\"244\" height=\"26\" rx=\"2\" fill=\"#047857\"/><rect x=\"9\" y=\"42\" width=\"242\" height=\"24\" rx=\"1\" stroke=\"#34d399\" stroke-width=\"2\" fill=\"none\"/><path d=\"M239.8,53.1 L248.2,53.1 L244,56.6 Z\" fill-rule=\"evenodd\" fill=\"#d1fae5\"/><rect x=\"8\" y=\"8\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#047857\"/><rect x=\"9\" y=\"9\" width=\"242\" height=\"25\" rx=\"1\" stroke=\"#34d399\" stroke-width=\"2\" fill=\"none\"/><path d=\"M239.8,20.6 L248.2,20.6 L244,24.1 Z\" fill-rule=\"evenodd\" fill=\"#75c0a5\"/></g><text x=\"13\" y=\"21.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#d1fae5\" textLength=\"151\" lengthAdjust=\"spacing\">comboBox (inputStyle)</text><text x=\"13\" y=\"54.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#d1fae5\" textLength=\"191\" lengthAdjust=\"spacing\">select (buttonStyle matched)</text></svg>","title":"select and comboBox use different surfaces","where":"NanoUI.Internal.Frame.Chrome (widgetVisualStyle)","why":"Both look the same when closed. `select` is a `NodeSelect` painted with `themeButton`; `comboBox` is a `NodeTextInput` painted with `themeInput`. An `inputStyle` scope styles `textInput`, `numericInput` and `comboBox`, so `select` is left mismatched."},{"category":"surface-input surface-panel","codeBad":"-- both axes fill: no well, no border\nscrollWith (grow . padAll 6) body","codeGood":"-- bounded height keeps the themeInput well\nscrollWith (fillW . fixedH 80 . padAll 6) body","fix":"Give embedded scrollers a fixed or bounded height (`fixedH`, `maxH`), or wrap a `grow` scroller in a styled `panelWith`.","id":"05","labelA":"grow: no well, no border, page background fill","labelB":"fixedH 80: bordered themeInput well, radius 0","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"96\" viewBox=\"0 0 260 96\"><defs><clipPath id=\"i5-bad-tclip_1\"><rect x=\"14\" y=\"77\" width=\"122\" height=\"5\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" fill=\"#18181b\"/><g><rect x=\"8\" y=\"8\" width=\"244\" height=\"80\" fill=\"#047857\"/><rect x=\"9\" y=\"9\" width=\"242\" height=\"78\" stroke=\"#34d399\" stroke-width=\"2\" fill=\"none\"/><rect x=\"238\" y=\"17\" width=\"8\" height=\"62\" rx=\"4\" fill=\"#146853\"/><rect x=\"238\" y=\"17\" width=\"8\" height=\"49\" rx=\"4\" fill=\"#93aca3\" fill-opacity=\"0.51\"/></g><text x=\"14\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"213\" lengthAdjust=\"spacing\">fixedH 80: uses themeInput well</text><text x=\"14\" y=\"43.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"165\" lengthAdjust=\"spacing\">cornerRadius forced to 0</text><text x=\"14\" y=\"64.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"118\" lengthAdjust=\"spacing\">Line 3 (scrollable)</text><g clip-path=\"url(#i5-bad-tclip_1)\"><text x=\"14\" y=\"85.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"118\" lengthAdjust=\"spacing\">Line 4 (scrollable)</text></g></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"96\" viewBox=\"0 0 260 96\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" fill=\"#18181b\"/><text x=\"14\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"188\" lengthAdjust=\"spacing\">scrollWith grow (fillW . fillH):</text><text x=\"14\" y=\"43.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"232\" lengthAdjust=\"spacing\">Drops the themeInput well and border</text><text x=\"14\" y=\"64.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"232\" lengthAdjust=\"spacing\">Paints the page background instead</text></svg>","title":"scrollWith changes surface with its sizing","where":"NanoUI.Internal.Frame.Paint (paintScrollSurface)","why":"When either axis is `Fixed` or `Fit`, `paintScrollSurface` draws a bordered `themeInput` well with `styleCornerRadius` forced to 0. When both axes are `Fill` (`scrollWith grow`), it treats the scroller as a full-window page scroller: it drops the border and fills with the page background (`pageBackground`, `themeWindow` by default)."},{"category":"surface-panel","codeBad":"callout Warning $ do\n  label \"Warning\"\n  card (label \"Inner card turns yellow\")","codeGood":"basePanel <- themePanel <$> uiTheme\ncallout Warning $ do\n  label \"Warning\"\n  styled (\\t -> t {themePanel = basePanel}) (card (label \"Clean card\"))","fix":"Capture `basePanel <- themePanel <$> uiTheme` before the callout and wrap inner panels in `styled (\\t -> t {themePanel = basePanel})`.","id":"06","labelA":"nested card inherits the Warning tint","labelB":"themePanel restored inside the callout","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"104\" viewBox=\"0 0 260 104\"><defs><clipPath id=\"i6-bad-tclip_1\"><rect x=\"30\" y=\"49\" width=\"221\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"104\" fill=\"#18181b\"/><g><defs><clipPath id=\"i6-bad-sclip_1\"><rect x=\"9\" y=\"9\" width=\"242\" height=\"72\"/></clipPath></defs><rect x=\"8\" y=\"8\" width=\"244\" height=\"74\" rx=\"2\" fill=\"#3a3328\"/><rect x=\"8.5\" y=\"8.5\" width=\"243\" height=\"73\" rx=\"1.5\" stroke=\"#ebb338\" stroke-width=\"1\" fill=\"none\"/><g clip-path=\"url(#i6-bad-sclip_1)\"><rect x=\"18\" y=\"39\" width=\"300\" height=\"37\" rx=\"2\" fill=\"#3a3328\"/><rect x=\"18.5\" y=\"39.5\" width=\"299\" height=\"36\" rx=\"1.5\" stroke=\"#ebb338\" stroke-width=\"1\" fill=\"none\"/></g></g><text x=\"18\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"144\" lengthAdjust=\"spacing\">Outer Warning callout</text><g clip-path=\"url(#i6-bad-tclip_1)\"><text x=\"30\" y=\"57.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"230\" lengthAdjust=\"spacing\">Nested card inherits the yellow tint</text></g></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"104\" viewBox=\"0 0 260 104\"><defs><clipPath id=\"i6-good-tclip_1\"><rect x=\"30\" y=\"49\" width=\"221\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"104\" fill=\"#18181b\"/><g><defs><clipPath id=\"i6-good-sclip_1\"><rect x=\"9\" y=\"9\" width=\"242\" height=\"72\"/></clipPath></defs><rect x=\"8\" y=\"8\" width=\"244\" height=\"74\" rx=\"2\" fill=\"#3a3328\"/><rect x=\"8.5\" y=\"8.5\" width=\"243\" height=\"73\" rx=\"1.5\" stroke=\"#ebb338\" stroke-width=\"1\" fill=\"none\"/><g clip-path=\"url(#i6-good-sclip_1)\"><rect x=\"18\" y=\"39\" width=\"300\" height=\"37\" rx=\"2\" fill=\"#222226\"/><rect x=\"18.5\" y=\"39.5\" width=\"299\" height=\"36\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/></g></g><text x=\"18\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"144\" lengthAdjust=\"spacing\">Outer Warning callout</text><g clip-path=\"url(#i6-good-tclip_1)\"><text x=\"30\" y=\"57.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"254\" lengthAdjust=\"spacing\">Nested card with restored themePanel</text></g></svg>","title":"callout tints nested panels","where":"NanoUI.Internal.Widgets.Layout (calloutWith)","why":"`calloutWith` wraps its body in `styled (panelStyle ...)`, so every `panel` or `card` inside the callout inherits the tinted background and border. `modal` and `popup` read `themePopup`, so their children keep the normal `themePanel`."},{"category":"surface-button","codeBad":"-- buttonStyle only reaches the off state\nstyled (buttonStyle (fillColor blue)) (toggleButton Warning \" On\" vTrue)","codeGood":"-- pair buttonStyle (off) with accentColor (on)\nstyled (buttonStyle (fillColor blue) . accentColor rose)\n  (toggleButton Accent \"On\" vTrue)","fix":"Change the tone field (`accentColor` for `Accent`, or the matching tone) to color the on state.","id":"07","labelA":"on state ignores buttonStyle","labelB":"buttonStyle for off, accentColor for on","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"80\" viewBox=\"0 0 260 80\"><defs><clipPath id=\"i7-bad-tclip_1\"><rect x=\"185.5\" y=\"16\" width=\"73.5\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" fill=\"#18181b\"/><g><defs><clipPath id=\"i7-bad-sclip_1\"><rect x=\"1\" y=\"1\" width=\"258\" height=\"78\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"79\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><g clip-path=\"url(#i7-bad-sclip_1)\"><rect x=\"181\" y=\"13\" width=\"133\" height=\"22\" rx=\"2\" fill=\"#f2b44c\"/><rect x=\"182\" y=\"14\" width=\"131\" height=\"20\" rx=\"1\" stroke=\"#f2b44c\" stroke-width=\"2\" fill=\"none\"/></g><rect x=\"13\" y=\"13\" width=\"160\" height=\"22\" rx=\"2\" fill=\"#0369a1\"/><rect x=\"14\" y=\"14\" width=\"158\" height=\"20\" rx=\"1\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"none\"/></g><text x=\"17.5\" y=\"24.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#e0f2fe\" textLength=\"152\" lengthAdjust=\"spacing\">OFF (uses buttonStyle)</text><g clip-path=\"url(#i7-bad-tclip_1)\"><text x=\"185.5\" y=\"24.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"125\" lengthAdjust=\"spacing\">ON (Warning wins)</text></g></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"80\" viewBox=\"0 0 260 80\"><defs><clipPath id=\"i7-good-tclip_1\"><rect x=\"150.5\" y=\"16\" width=\"108.5\" height=\"17\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" fill=\"#18181b\"/><g><defs><clipPath id=\"i7-good-sclip_1\"><rect x=\"1\" y=\"1\" width=\"258\" height=\"78\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"79\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><g clip-path=\"url(#i7-good-sclip_1)\"><rect x=\"146\" y=\"13\" width=\"123\" height=\"22\" rx=\"2\" fill=\"#e11d48\"/><rect x=\"147\" y=\"14\" width=\"121\" height=\"20\" rx=\"1\" stroke=\"#e11d48\" stroke-width=\"2\" fill=\"none\"/></g><rect x=\"13\" y=\"13\" width=\"125\" height=\"22\" rx=\"2\" fill=\"#0369a1\"/><rect x=\"14\" y=\"14\" width=\"123\" height=\"20\" rx=\"1\" stroke=\"#38bdf8\" stroke-width=\"2\" fill=\"none\"/></g><text x=\"18\" y=\"24.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#e0f2fe\" textLength=\"117\" lengthAdjust=\"spacing\">OFF (buttonStyle)</text><g clip-path=\"url(#i7-good-tclip_1)\"><text x=\"150.5\" y=\"24.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#ffffff\" textLength=\"115\" lengthAdjust=\"spacing\">ON (accentColor)</text></g></svg>","title":"toggleButton ignores buttonStyle when on","where":"NanoUI.Internal.Frame.Chrome (widgetVisualStyle)","why":"When `toggleButton` is off, `widgetVisualStyle` returns `themeButton`, so `buttonStyle` applies. When it is on, `widgetVisualStyle` overwrites `styleBg`, `styleHoverBg` and `styleBorder` with `toneColor theme tone`, and `styleFg` with `readableOn theme c`."},{"category":"surface-input surface-button","codeBad":"-- focus swaps the background to styleActiveBg\nstyled (inputStyle (background teal)) (textInput txt)","codeGood":"-- fillColor updates all three background fields\nstyled (inputStyle (fillColor teal)) (textInput txt)","fix":"Use `fillColor` (or `tinted`) on `buttonStyle`, `inputStyle` and `popupStyle`; it updates `styleBg`, `styleHoverBg` and `styleActiveBg` together.","id":"08","labelA":"background teal: focused field reverts","labelB":"fillColor teal: focused field keeps the color","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"88\" viewBox=\"0 0 260 88\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"88\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"88\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"87\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"41\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#0d9488\"/><rect x=\"8.5\" y=\"41.5\" width=\"243\" height=\"26\" rx=\"1.5\" stroke=\"#464850\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"8\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#0e0e11\"/><rect x=\"8.5\" y=\"8.5\" width=\"243\" height=\"26\" rx=\"1.5\" stroke=\"#589cf6\" stroke-width=\"1\" fill=\"none\"/><rect x=\"79\" y=\"14\" width=\"1\" height=\"15\" fill=\"#ffffff\"/></g><text x=\"13\" y=\"21.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#ffffff\" textLength=\"116\" lengthAdjust=\"spacing\">Focused: lost teal</text><text x=\"13\" y=\"54.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#ffffff\" textLength=\"169\" lengthAdjust=\"spacing\">Unfocused: keeps teal bg</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"88\" viewBox=\"0 0 260 88\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"88\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"88\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"87\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"41\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#0d9488\"/><rect x=\"8.5\" y=\"41.5\" width=\"243\" height=\"26\" rx=\"1.5\" stroke=\"#464850\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"8\" width=\"244\" height=\"27\" rx=\"2\" fill=\"#0b7970\"/><rect x=\"8.5\" y=\"8.5\" width=\"243\" height=\"26\" rx=\"1.5\" stroke=\"#589cf6\" stroke-width=\"1\" fill=\"none\"/><rect x=\"78\" y=\"14\" width=\"1\" height=\"15\" fill=\"#ffffff\"/></g><text x=\"13\" y=\"21.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#ffffff\" textLength=\"149\" lengthAdjust=\"spacing\">Focused: fillColor kept</text><text x=\"13\" y=\"54.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#ffffff\" textLength=\"165\" lengthAdjust=\"spacing\">Unfocused: fillColor kept</text></svg>","title":"background resets on focus","where":"NanoUI.Internal.Style (background vs fillColor), NanoUI.Internal.Frame.Chrome (widgetVisualStyle)","why":"`background c` only sets `styleBg`. When a `textInput` or `textArea` gains focus, `widgetVisualStyle` sets its background to `styleActiveBg (themeInput theme)`, so an input styled with `background teal` loses the teal when clicked."},{"category":"surface-panel","codeBad":"styled (panelStyle (borderWidth 8)) $\n  panelWith tight (label \"Overlapped\")","codeGood":"styled (panelStyle (borderWidth 6 . borderLeft)) $\n  panelWith (padLRTB 12 8 8 8) (label \"Padded\")","fix":"Add matching padding (`padAll`, `padLeft`, `padLRTB`) when you increase `borderWidth`.","id":"09","labelA":"borderWidth 8 on tight: stroke over text","labelB":"borderLeft 6 with padLRTB 12 8 8 8","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"80\" viewBox=\"0 0 260 80\"><defs><clipPath id=\"i9-bad-tclip_1\"><rect x=\"16\" y=\"16\" width=\"228\" height=\"1\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" fill=\"#18181b\"/><g><rect x=\"8\" y=\"8\" width=\"244\" height=\"17\" rx=\"2\" fill=\"#222226\"/><rect x=\"12\" y=\"12\" width=\"236\" height=\"9\" stroke=\"#f43f5e\" stroke-width=\"8\" fill=\"none\"/></g><g clip-path=\"url(#i9-bad-tclip_1)\"><text x=\"8\" y=\"16.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"232\" lengthAdjust=\"spacing\">tight + borderWidth 8 overlaps text</text></g></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"80\" viewBox=\"0 0 260 80\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"80\" fill=\"#18181b\"/><g><rect x=\"8\" y=\"8\" width=\"244\" height=\"33\" rx=\"2\" fill=\"#222226\"/><rect x=\"8\" y=\"8\" width=\"6\" height=\"33\" fill=\"#f43f5e\"/></g><text x=\"20\" y=\"24.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"224\" lengthAdjust=\"spacing\">borderLeft 6 + padLeft 12 clears stroke</text></svg>","title":"borderWidth does not add layout space","where":"NanoUI.Internal.Frame.Chrome (strokeStyledSides), NanoUI.Internal.Layout.Solve","why":"Theme scopes never change layout geometry. `borderWidth 8` draws an 8px inset stroke without adding padding, so on a `tight` container it paints over child text. When `borderSides` is not all four sides, `strokeStyledSides` draws flat edge quads and ignores `cornerRadius`."},{"category":"surface-button","codeBad":"styled (primary . destructive) (button \"Which wins?\") -- primary\nbuttonWith (fixedW 110 . fixedW 220) \"Width?\"        -- 110px","codeGood":"styled primary $ styled destructive $ button \"Inner destructive wins\"","fix":"Put the winning override on the left in a `(.)` chain, and innermost when nesting `styled`.","id":"10","labelA":"(.) chain: leftmost runs last and wins","labelB":"nested styled: innermost wins","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"84\" viewBox=\"0 0 260 84\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"83\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"11\" y=\"45\" width=\"110\" height=\"22\" rx=\"2\" fill=\"#34343a\"/><rect x=\"11.5\" y=\"45.5\" width=\"109\" height=\"21\" rx=\"1.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><rect x=\"11\" y=\"11\" width=\"144\" height=\"22\" rx=\"2\" fill=\"#589cf6\"/><rect x=\"11.5\" y=\"11.5\" width=\"143\" height=\"21\" rx=\"1.5\" stroke=\"#589cf6\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"15\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"136\" lengthAdjust=\"spacing\">primary . destructive</text><text x=\"16\" y=\"56.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f8f7f5\" textLength=\"101\" lengthAdjust=\"spacing\">fixedW 110 wi...</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"84\" viewBox=\"0 0 260 84\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"84\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"83\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"11\" y=\"11\" width=\"207\" height=\"22\" rx=\"2\" fill=\"#fca5a5\"/><rect x=\"11.5\" y=\"11.5\" width=\"206\" height=\"21\" rx=\"1.5\" stroke=\"#fca5a5\" stroke-width=\"1\" fill=\"none\"/></g><text x=\"15.5\" y=\"22.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"199\" lengthAdjust=\"spacing\">nested: inner destructive wins</text></svg>","title":"modifier order in (.) and styled","where":"NanoUI.Internal.Style, function composition","why":"Modifiers are functions. In `(f . g) x`, `g` runs first, then `f`, so the leftmost modifier wins: `primary . destructive` is `primary`, and `fixedW 110 . fixedW 220` is 110. Nested scopes run outside in: `styled outer (styled inner view)` makes the inner scope win."},{"category":"surface-panel surface-button","codeBad":"-- buttonStyle does not reach TabUnderline or TabContained\nstyled (buttonStyle myStyle) (tabBar active tabsList)","codeGood":"-- panelStyle and accentColor style the tab strip\nstyled (panelStyle myPanel . accentColor myAccent) (tabBar active tabsList)","fix":"Style tabs with `panelStyle` and `accentColor`.","id":"11","labelA":"buttonStyle: TabUnderline and TabContained unchanged","labelB":"panelStyle and accentColor: headers respond","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"96\" viewBox=\"0 0 260 96\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" fill=\"#18181b\"/><g><defs><clipPath id=\"i11-bad-sclip_1\"><rect x=\"79\" y=\"48\" width=\"62\" height=\"30\"/></clipPath><clipPath id=\"i11-bad-sclip_2\"><rect x=\"14\" y=\"48\" width=\"63\" height=\"30\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" rx=\"2\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"95\" rx=\"1.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"8\" y=\"77\" width=\"244\" height=\"1\" fill=\"#36363e\"/><g clip-path=\"url(#i11-bad-sclip_1)\"><rect x=\"79\" y=\"48\" width=\"62\" height=\"38\" rx=\"7\" fill=\"#eceae6\" fill-opacity=\"0.047\"/></g><g clip-path=\"url(#i11-bad-sclip_2)\"><rect x=\"14\" y=\"48\" width=\"63\" height=\"38\" rx=\"7\" fill=\"#222226\"/><rect x=\"14.5\" y=\"48.5\" width=\"62\" height=\"37\" rx=\"6.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/></g><rect x=\"8\" y=\"37\" width=\"244\" height=\"1\" fill=\"#3e4048\"/><rect x=\"8\" y=\"36\" width=\"63\" height=\"2\" rx=\"1\" fill=\"#589cf6\"/></g><text x=\"20\" y=\"23.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"39\" lengthAdjust=\"spacing\">Tab A</text><text x=\"85\" y=\"23.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#c5c2bb\" textLength=\"38\" lengthAdjust=\"spacing\">Tab B</text><text x=\"26\" y=\"63.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"39\" lengthAdjust=\"spacing\">Tab A</text><text x=\"91\" y=\"63.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#c5c2bb\" textLength=\"38\" lengthAdjust=\"spacing\">Tab B</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"96\" viewBox=\"0 0 260 96\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" fill=\"#18181b\"/><g><defs><clipPath id=\"i11-good-sclip_1\"><rect x=\"79\" y=\"48\" width=\"62\" height=\"30\"/></clipPath><clipPath id=\"i11-good-sclip_2\"><rect x=\"14\" y=\"48\" width=\"63\" height=\"30\"/></clipPath></defs><rect x=\"0\" y=\"0\" width=\"260\" height=\"96\" rx=\"2\" fill=\"#581c87\"/><rect x=\"1\" y=\"1\" width=\"258\" height=\"94\" rx=\"1\" stroke=\"#c084fc\" stroke-width=\"2\" fill=\"none\"/><rect x=\"8\" y=\"77\" width=\"244\" height=\"1\" fill=\"#c084fc\"/><g clip-path=\"url(#i11-good-sclip_1)\"><rect x=\"79\" y=\"48\" width=\"62\" height=\"38\" rx=\"7\" fill=\"#f3e8ff\" fill-opacity=\"0.047\"/></g><g clip-path=\"url(#i11-good-sclip_2)\"><rect x=\"14\" y=\"48\" width=\"63\" height=\"38\" rx=\"7\" fill=\"#581c87\"/><rect x=\"14.5\" y=\"48.5\" width=\"62\" height=\"37\" rx=\"6.5\" stroke=\"#c084fc\" stroke-width=\"1\" fill=\"none\"/></g><rect x=\"8\" y=\"37\" width=\"244\" height=\"1\" fill=\"#3e4048\"/><rect x=\"8\" y=\"36\" width=\"63\" height=\"2\" rx=\"1\" fill=\"#e11d48\"/></g><text x=\"20\" y=\"23.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f3e8ff\" textLength=\"39\" lengthAdjust=\"spacing\">Tab A</text><text x=\"85\" y=\"23.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#c7c1c4\" textLength=\"38\" lengthAdjust=\"spacing\">Tab B</text><text x=\"26\" y=\"63.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#f3e8ff\" textLength=\"39\" lengthAdjust=\"spacing\">Tab A</text><text x=\"91\" y=\"63.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#c7c1c4\" textLength=\"38\" lengthAdjust=\"spacing\">Tab B</text></svg>","title":"tabs read themePanel, not themeButton","where":"NanoUI.Internal.Frame.Chrome (tabHeaderVisualStyle)","why":"Tab headers are `NodeButton`s, but `tabHeaderVisualStyle` computes their colors from `themePanel` and `themeAccent`. `buttonStyle` has no effect on `TabUnderline`, `TabPill` or `TabContained`; only `TabSegmented` reads `styleBorder` from `themeButton` for its active border and luminance comparison."},{"category":"framesvg","codeBad":"setDrawSquareGeometry ctx True -- flattens button and panel radius to 0\n-- newPixelContext's 16px monospace metrics distort textLength","codeGood":"-- Render inside withSdl with DefaultFont and @font-face\nctx <- newContext\nsetDrawRecordOps ctx True\nsetDrawExternalText ctx True","fix":"Use `setDrawRecordOps ctx True` and `setDrawSquareGeometry ctx False`, render inside `withSdl` with `DefaultFont` and `@font-face`, and set `fsIdPrefix` per document.","id":"12","labelA":"square geometry on: rounded corners flattened","labelB":"square geometry off: rounded corners preserved","svgA":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#222226\"/><rect x=\"0\" y=\"0\" width=\"260\" height=\"1\" fill=\"#36363e\"/><rect x=\"0\" y=\"91\" width=\"260\" height=\"1\" fill=\"#36363e\"/><rect x=\"0\" y=\"1\" width=\"1\" height=\"90\" fill=\"#36363e\"/><rect x=\"259\" y=\"1\" width=\"1\" height=\"90\" fill=\"#36363e\"/><rect x=\"11\" y=\"34\" width=\"79\" height=\"22\" fill=\"#589cf6\"/><rect x=\"11\" y=\"34\" width=\"79\" height=\"1\" fill=\"#589cf6\"/><rect x=\"11\" y=\"55\" width=\"79\" height=\"1\" fill=\"#589cf6\"/><rect x=\"11\" y=\"35\" width=\"1\" height=\"20\" fill=\"#589cf6\"/><rect x=\"89\" y=\"35\" width=\"1\" height=\"20\" fill=\"#589cf6\"/></g><g><rect x=\"98\" y=\"34\" width=\"44\" height=\"24\" rx=\"12\" fill=\"#589cf6\"/><rect x=\"98.5\" y=\"34.5\" width=\"43\" height=\"23\" rx=\"11.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><circle cx=\"130\" cy=\"46\" r=\"9\" fill=\"#ffffff\"/></g><text x=\"8\" y=\"16.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"218\" lengthAdjust=\"spacing\">SquareGeo=True flattens rx to 0:</text><text x=\"15\" y=\"45.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"71\" lengthAdjust=\"spacing\">Flat Button</text></svg>","svgB":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"260\" height=\"92\" viewBox=\"0 0 260 92\"><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" fill=\"#18181b\"/><g><rect x=\"0\" y=\"0\" width=\"260\" height=\"92\" rx=\"10\" fill=\"#222226\"/><rect x=\"0.5\" y=\"0.5\" width=\"259\" height=\"91\" rx=\"9.5\" stroke=\"#36363e\" stroke-width=\"1\" fill=\"none\"/><rect x=\"11\" y=\"34\" width=\"90\" height=\"22\" rx=\"10\" fill=\"#589cf6\"/><rect x=\"11.5\" y=\"34.5\" width=\"89\" height=\"21\" rx=\"9.5\" stroke=\"#589cf6\" stroke-width=\"1\" fill=\"none\"/></g><g><rect x=\"109\" y=\"34\" width=\"44\" height=\"24\" rx=\"12\" fill=\"#589cf6\"/><rect x=\"109.5\" y=\"34.5\" width=\"43\" height=\"23\" rx=\"11.5\" stroke=\"#4a4c54\" stroke-width=\"1\" fill=\"none\"/><circle cx=\"141\" cy=\"46\" r=\"9\" fill=\"#ffffff\"/></g><text x=\"8\" y=\"16.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#eceae6\" textLength=\"207\" lengthAdjust=\"spacing\">SquareGeo=False keeps rx=10:</text><text x=\"15.5\" y=\"45.5\" dominant-baseline=\"central\" font-size=\"14\" font-family=\"Inter, 'Segoe UI', system-ui, sans-serif\" xml:space=\"preserve\" fill=\"#18181b\" textLength=\"82\" lengthAdjust=\"spacing\">Rounded Pill</text></svg>","title":"frameToSvg quirks","where":"NanoUI.Draw.FrameSvg (frameToSvg), NanoUI.Backend.Sdl (withSdl), NanoUI.Testing (newPixelContext)","why":"A few things matter for `frameToSvg`. Widget shapes export only from a context with `setDrawRecordOps ctx True`. `setDrawSquareGeometry ctx True` makes rounded rects and strokes draw as 0-radius quads, flattening `cornerRadius` on `button`, `panel` and `textInput`; `NodeDrawing` widgets still render smooth rects and circles from cached ops. `newPixelContext` defaults to 16px monospace metrics, so load `inter.ttf` through `withSdl` and embed it with `@font-face` for matching `textLength`. Every document numbers its clip and gradient IDs from 1 (`tclip_1`, `sclip_1`, `grad_1`), so give each its own `fsIdPrefix` when inlining several SVGs."}];
